Looking at the kernel, I need to:

1. Add HLS INTERFACE pragmas for all arguments
2. Pipeline the innermost loops for better throughput
3. Partition local/parameter arrays for parallel access
4. Handle the 2D array arguments properly for HLS synthesis

The key observations:
- Arrays are passed as 2D arrays (fixed-size dimensions from header macros)
- Two loop nests: first computes `tmp = alpha * A * B`, second computes `D = beta * D + tmp * C`
- The innermost `k` loops are reduction loops — pipeline these
- `tmp` is local to the computation (written then read), so we can partition it

```cpp
#include "2mm.h"

extern "C" {

void kernel_2mm(   
		double alpha,
		double beta,
		double tmp[ NI + 0][NJ + 0],
		double A[ NI + 0][NK + 0],
		double B[ NK + 0][NJ + 0],
		double C[ NJ + 0][NL + 0],
		double D[ NI + 0][NL + 0])
{
#pragma HLS INTERFACE s_axilite port=alpha    bundle=control
#pragma HLS INTERFACE s_axilite port=beta     bundle=control
#pragma HLS INTERFACE m_axi     port=tmp      offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=tmp      bundle=control
#pragma HLS INTERFACE m_axi     port=A        offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=A        bundle=control
#pragma HLS INTERFACE m_axi     port=B        offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=B        bundle=control
#pragma HLS INTERFACE m_axi     port=C        offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=C        bundle=control
#pragma HLS INTERFACE m_axi     port=D        offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=D        bundle=control
#pragma HLS INTERFACE s_axilite port=return   bundle=control

    // Local tile buffers to avoid repeated global memory accesses
    double local_tmp[NI][NJ];
    double local_A[NI][NK];
    double local_B[NK][NJ];
    double local_C[NJ][NL];
    double local_D[NI][NL];

#pragma HLS ARRAY_PARTITION variable=local_tmp cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=local_A   cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=local_B   cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=local_C   cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=local_D   cyclic factor=8 dim=2

    // Load A from global memory
    load_A:
    for (int i = 0; i < NI; i++) {
        for (int k = 0; k < NK; k++) {
#pragma HLS PIPELINE II=1
            local_A[i][k] = A[i][k];
        }
    }

    // Load B from global memory
    load_B:
    for (int k = 0; k < NK; k++) {
        for (int j = 0; j < NJ; j++) {
#pragma HLS PIPELINE II=1
            local_B[k][j] = B[k][j];
        }
    }

    // Load C from global memory
    load_C:
    for (int j = 0; j < NJ; j++) {
        for (int l = 0; l < NL; l++) {
#pragma HLS PIPELINE II=1
            local_C[j][l] = C[j][l];
        }
    }

    // Load D from global memory
    load_D:
    for (int i = 0; i < NI; i++) {
        for (int l = 0; l < NL; l++) {
#pragma HLS PIPELINE II=1
            local_D[i][l] = D[i][l];
        }
    }

    // First loop nest: tmp[i][j] = alpha * A[i][k] * B[k][j]
    loop1_i:
    for (int i = 0; i < NI; i++) {
        loop1_j:
        for (int j = 0; j < NJ; j++) {
            double acc = 0.0;
            loop1_k:
            for (int k = 0; k < NK; ++k) {
#pragma HLS PIPELINE II=1
                acc += alpha * local_A[i][k] * local_B[k][j];
            }
            local_tmp[i][j] = acc;
        }
    }

    // Second loop nest: D[i][j] = beta * D[i][j] + tmp[i][k] * C[k][j]
    loop2_i:
    for (int i = 0; i < NI; i++) {
        loop2_j:
        for (int j = 0; j < NL; j++) {
            double acc = local_D[i][j] * beta;
            loop2_k:
            for (int k = 0; k < NJ; ++k) {
#pragma HLS PIPELINE II=1
                acc += local_tmp[i][k] * local_C[k][j];
            }
            local_D[i][j] = acc;
        }
    }

    // Store tmp to global memory
    store_tmp:
    for (int i = 0; i < NI; i++) {
        for (int j = 0; j < NJ; j++) {
#pragma HLS PIPELINE II=1
            tmp[i][j] = local_tmp[i][j];
        }
    }

    // Store D to global memory
    store_D:
    for (int i = 0; i < NI; i++) {
        for (int l = 0; l < NL; l++) {
#pragma HLS PIPELINE II=1
            D[i][l] = local_D[i][l];
        }
    }
}

} // extern "C"
```

Looking at the current code, it already has local buffers but loads the entire arrays at once. True tiling means processing data in chunks/tiles to improve locality and enable better memory access patterns. I'll restructure this to use tile-based processing with smaller tiles (e.g., 8×8 or similar tile sizes) where the computation loops iterate over tiles.

The key insight for 2mm is:
- **Phase 1**: `tmp[i][j] = alpha * sum_k(A[i][k] * B[k][j])`
- **Phase 2**: `D[i][l] = beta * D[i][l] + sum_k(tmp[i][k] * C[k][l])`

I'll tile the outer dimensions and buffer tiles of A, B, C, D, tmp locally.

```cpp
#include "2mm.h"

// Tile sizes chosen to fit in local BRAM
#define TI 8
#define TJ 8
#define TK 8
#define TL 8

extern "C" {

void kernel_2mm(   
		double alpha,
		double beta,
		double tmp[ NI + 0][NJ + 0],
		double A[ NI + 0][NK + 0],
		double B[ NK + 0][NJ + 0],
		double C[ NJ + 0][NL + 0],
		double D[ NI + 0][NL + 0])
{
#pragma HLS INTERFACE s_axilite port=alpha    bundle=control
#pragma HLS INTERFACE s_axilite port=beta     bundle=control
#pragma HLS INTERFACE m_axi     port=tmp      offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=tmp      bundle=control
#pragma HLS INTERFACE m_axi     port=A        offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=A        bundle=control
#pragma HLS INTERFACE m_axi     port=B        offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=B        bundle=control
#pragma HLS INTERFACE m_axi     port=C        offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=C        bundle=control
#pragma HLS INTERFACE m_axi     port=D        offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=D        bundle=control
#pragma HLS INTERFACE s_axilite port=return   bundle=control

    // -------------------------------------------------------
    // Phase 1: tmp[i][j] = alpha * sum_k( A[i][k] * B[k][j] )
    // Tile over i, j, k dimensions
    // -------------------------------------------------------

    // Accumulator tile for tmp (one (TI x TJ) output tile at a time)
    double acc_tmp[TI][TJ];
    double tile_A[TI][TK];
    double tile_B[TK][TJ];
#pragma HLS ARRAY_PARTITION variable=acc_tmp complete dim=2
#pragma HLS ARRAY_PARTITION variable=tile_A  complete dim=2
#pragma HLS ARRAY_PARTITION variable=tile_B  complete dim=2

    phase1_i:
    for (int ii = 0; ii < NI; ii += TI) {
        phase1_j:
        for (int jj = 0; jj < NJ; jj += TJ) {

            // Initialize accumulator tile
            init_acc:
            for (int i = 0; i < TI; i++) {
#pragma HLS PIPELINE II=1
                for (int j = 0; j < TJ; j++) {
#pragma HLS UNROLL
                    acc_tmp[i][j] = 0.0;
                }
            }

            // Accumulate over k tiles
            phase1_k:
            for (int kk = 0; kk < NK; kk += TK) {

                // Load tile of A[ii:ii+TI][kk:kk+TK]
                load_A:
                for (int i = 0; i < TI; i++) {
#pragma HLS PIPELINE II=1
                    for (int k = 0; k < TK; k++) {
#pragma HLS UNROLL
                        int gi = ii + i;
                        int gk = kk + k;
                        tile_A[i][k] = (gi < NI && gk < NK) ? A[gi][gk] : 0.0;
                    }
                }

                // Load tile of B[kk:kk+TK][jj:jj+TJ]
                load_B:
                for (int k = 0; k < TK; k++) {
#pragma HLS PIPELINE II=1
                    for (int j = 0; j < TJ; j++) {
#pragma HLS UNROLL
                        int gk = kk + k;
                        int gj = jj + j;
                        tile_B[k][j] = (gk < NK && gj < NJ) ? B[gk][gj] : 0.0;
                    }
                }

                // Compute tile contribution
                compute1:
                for (int i = 0; i < TI; i++) {
                    for (int j = 0; j < TJ; j++) {
#pragma HLS PIPELINE II=1
                        double sum = 0.0;
                        for (int k = 0; k < TK; k++) {
#pragma HLS UNROLL
                            sum += alpha * tile_A[i][k] * tile_B[k][j];
                        }
                        acc_tmp[i][j] += sum;
                    }
                }
            } // kk

            // Store accumulated tmp tile to global memory
            store_tmp:
            for (int i = 0; i < TI; i++) {
#pragma HLS PIPELINE II=1
                for (int j = 0; j < TJ; j++) {
#pragma HLS UNROLL
                    int gi = ii + i;
                    int gj = jj + j;
                    if (gi < NI && gj < NJ)
                        tmp[gi][gj] = acc_tmp[i][j];
                }
            }

        } // jj
    } // ii

    // -------------------------------------------------------
    // Phase 2: D[i][l] = beta * D[i][l] + sum_k( tmp[i][k] * C[k][l] )
    // Tile over i, l, k(=j) dimensions
    // -------------------------------------------------------

    double acc_D[TI][TL];
    double tile_tmp[TI][TJ];
    double tile_C[TJ][TL];
#pragma HLS ARRAY_PARTITION variable=acc_D   complete dim=2
#pragma HLS ARRAY_PARTITION variable=tile_tmp complete dim=2
#pragma HLS ARRAY_PARTITION variable=tile_C  complete dim=2

    phase2_i:
    for (int ii = 0; ii < NI; ii += TI) {
        phase2_l:
        for (int ll = 0; ll < NL; ll += TL) {

            // Load and initialize accumulator: acc_D = beta * D[ii:ii+TI][ll:ll+TL]
            init_D:
            for (int i = 0; i < TI; i++) {
#pragma HLS PIPELINE II=1
                for (int l = 0; l < TL; l++) {
#pragma HLS UNROLL
                    int gi = ii + i;
                    int gl = ll + l;
                    acc_D[i][l] = (gi < NI && gl < NL) ? beta * D[gi][gl] : 0.0;
                }
            }

            // Accumulate over j tiles (k in the second loop nest uses j as reduction var)
            phase2_k:
            for (int jj = 0; jj < NJ; jj += TJ) {

                // Load tile of tmp[ii:ii+TI][jj:jj+TJ]
                load_tmp:
                for (int i = 0; i < TI; i++) {
#pragma HLS PIPELINE II=1
                    for (int j = 0; j < TJ; j++) {
#pragma HLS UNROLL
                        int gi = ii + i;
                        int gj = jj + j;
                        tile_tmp[i][j] = (gi < NI && gj < NJ) ? tmp[gi][gj] : 0.0;
                    }
                }

                // Load tile of C[jj:jj+TJ][ll:ll+TL]
                load_C:
                for (int j = 0; j < TJ; j++) {
#pragma HLS PIPELINE II=1
                    for (int l = 0; l < TL; l++) {
#pragma HLS UNROLL
                        int gj = jj + j;
                        int gl = ll + l;
                        tile_C[j][l] = (gj < NJ && gl < NL) ? C[gj][gl] : 0.0;
                    }
                }

                // Compute tile contribution
                compute2:
                for (int i = 0; i < TI; i++) {
                    for (int l = 0; l < TL; l++) {
#pragma HLS PIPELINE II=1
                        double sum = 0.0;
                        for (int j = 0; j < TJ; j++) {
#pragma HLS UNROLL
                            sum += tile_tmp[i][j] * tile_C[j][l];
                        }
                        acc_D[i][l] += sum;
                    }
                }
            } // jj

            // Store D tile back to global memory
            store_D:
            for (int i = 0; i < TI; i++) {
#pragma HLS PIPELINE II=1
                for (int l = 0; l < TL; l++) {
#pragma HLS UNROLL
                    int gi = ii + i;
                    int gl = ll + l;
                    if (gi < NI && gl < NL)
                        D[gi][gl] = acc_D[i][l];
                }
            }

        } // ll
    } // ii
}

} // extern "C"
```

Looking at the current code, pipeline pragmas are already present on many loops. However, the `compute1` and `compute2` loops have the pipeline on the inner `j`/`l` loop but not on the outer `i` loop, which means the outer loop iterates sequentially. I need to:

1. Move `#pragma HLS PIPELINE II=1` to the outermost compute loops (`compute1` and `compute2`) with the inner loops unrolled
2. Add `#pragma HLS DEPENDENCE` for the accumulator arrays to handle false inter-iteration dependencies
3. Add `#pragma HLS LOOP_TRIPCOUNT` for clarity
4. Ensure array partitioning supports parallel access

```cpp
#include "2mm.h"

// Tile sizes chosen to fit in local BRAM
#define TI 8
#define TJ 8
#define TK 8
#define TL 8

extern "C" {

void kernel_2mm(   
		double alpha,
		double beta,
		double tmp[ NI + 0][NJ + 0],
		double A[ NI + 0][NK + 0],
		double B[ NK + 0][NJ + 0],
		double C[ NJ + 0][NL + 0],
		double D[ NI + 0][NL + 0])
{
#pragma HLS INTERFACE s_axilite port=alpha    bundle=control
#pragma HLS INTERFACE s_axilite port=beta     bundle=control
#pragma HLS INTERFACE m_axi     port=tmp      offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=tmp      bundle=control
#pragma HLS INTERFACE m_axi     port=A        offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=A        bundle=control
#pragma HLS INTERFACE m_axi     port=B        offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=B        bundle=control
#pragma HLS INTERFACE m_axi     port=C        offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=C        bundle=control
#pragma HLS INTERFACE m_axi     port=D        offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=D        bundle=control
#pragma HLS INTERFACE s_axilite port=return   bundle=control

    // -------------------------------------------------------
    // Phase 1: tmp[i][j] = alpha * sum_k( A[i][k] * B[k][j] )
    // Tile over i, j, k dimensions
    // -------------------------------------------------------

    // Accumulator tile for tmp (one (TI x TJ) output tile at a time)
    double acc_tmp[TI][TJ];
    double tile_A[TI][TK];
    double tile_B[TK][TJ];
#pragma HLS ARRAY_PARTITION variable=acc_tmp complete dim=1
#pragma HLS ARRAY_PARTITION variable=acc_tmp complete dim=2
#pragma HLS ARRAY_PARTITION variable=tile_A  complete dim=1
#pragma HLS ARRAY_PARTITION variable=tile_A  complete dim=2
#pragma HLS ARRAY_PARTITION variable=tile_B  complete dim=1
#pragma HLS ARRAY_PARTITION variable=tile_B  complete dim=2

    phase1_i:
    for (int ii = 0; ii < NI; ii += TI) {
#pragma HLS LOOP_TRIPCOUNT min=5 max=5
        phase1_j:
        for (int jj = 0; jj < NJ; jj += TJ) {
#pragma HLS LOOP_TRIPCOUNT min=7 max=7

            // Initialize accumulator tile
            init_acc:
            for (int i = 0; i < TI; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=TI max=TI
                for (int j = 0; j < TJ; j++) {
#pragma HLS UNROLL
                    acc_tmp[i][j] = 0.0;
                }
            }

            // Accumulate over k tiles
            phase1_k:
            for (int kk = 0; kk < NK; kk += TK) {
#pragma HLS LOOP_TRIPCOUNT min=9 max=9

                // Load tile of A[ii:ii+TI][kk:kk+TK]
                load_A:
                for (int i = 0; i < TI; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=TI max=TI
                    for (int k = 0; k < TK; k++) {
#pragma HLS UNROLL
                        int gi = ii + i;
                        int gk = kk + k;
                        tile_A[i][k] = (gi < NI && gk < NK) ? A[gi][gk] : 0.0;
                    }
                }

                // Load tile of B[kk:kk+TK][jj:jj+TJ]
                load_B:
                for (int k = 0; k < TK; k++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=TK max=TK
                    for (int j = 0; j < TJ; j++) {
#pragma HLS UNROLL
                        int gk = kk + k;
                        int gj = jj + j;
                        tile_B[k][j] = (gk < NK && gj < NJ) ? B[gk][gj] : 0.0;
                    }
                }

                // Compute tile contribution
                // Pipeline the i-loop; unroll j and k to enable full parallelism
                compute1:
                for (int i = 0; i < TI; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=TI max=TI
#pragma HLS DEPENDENCE variable=acc_tmp inter false
                    for (int j = 0; j < TJ; j++) {
#pragma HLS UNROLL
                        double sum = 0.0;
                        for (int k = 0; k < TK; k++) {
#pragma HLS UNROLL
                            sum += alpha * tile_A[i][k] * tile_B[k][j];
                        }
                        acc_tmp[i][j] += sum;
                    }
                }
            } // kk

            // Store accumulated tmp tile to global memory
            store_tmp:
            for (int i = 0; i < TI; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=TI max=TI
                for (int j = 0; j < TJ; j++) {
#pragma HLS UNROLL
                    int gi = ii + i;
                    int gj = jj + j;
                    if (gi < NI && gj < NJ)
                        tmp[gi][gj] = acc_tmp[i][j];
                }
            }

        } // jj
    } // ii

    // -------------------------------------------------------
    // Phase 2: D[i][l] = beta * D[i][l] + sum_k( tmp[i][k] * C[k][l] )
    // Tile over i, l, k(=j) dimensions
    // -------------------------------------------------------

    double acc_D[TI][TL];
    double tile_tmp[TI][TJ];
    double tile_C[TJ][TL];
#pragma HLS ARRAY_PARTITION variable=acc_D    complete dim=1
#pragma HLS ARRAY_PARTITION variable=acc_D    complete dim=2
#pragma HLS ARRAY_PARTITION variable=tile_tmp complete dim=1
#pragma HLS ARRAY_PARTITION variable=tile_tmp complete dim=2
#pragma HLS ARRAY_PARTITION variable=tile_C   complete dim=1
#pragma HLS ARRAY_PARTITION variable=tile_C   complete dim=2

    phase2_i:
    for (int ii = 0; ii < NI; ii += TI) {
#pragma HLS LOOP_TRIPCOUNT min=5 max=5
        phase2_l:
        for (int ll = 0; ll < NL; ll += TL) {
#pragma HLS LOOP_TRIPCOUNT min=10 max=10

            // Load and initialize accumulator: acc_D = beta * D[ii:ii+TI][ll:ll+TL]
            init_D:
            for (int i = 0; i < TI; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=TI max=TI
                for (int l = 0; l < TL; l++) {
#pragma HLS UNROLL
                    int gi = ii + i;
                    int gl = ll + l;
                    acc_D[i][l] = (gi < NI && gl < NL) ? beta * D[gi][gl] : 0.0;
                }
            }

            // Accumulate over j tiles (k in the second loop nest uses j as reduction var)
            phase2_k:
            for (int jj = 0; jj < NJ; jj += TJ) {
#pragma HLS LOOP_TRIPCOUNT min=7 max=7

                // Load tile of tmp[ii:ii+TI][jj:jj+TJ]
                load_tmp:
                for (int i = 0; i < TI; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=TI max=TI
                    for (int j = 0; j < TJ; j++) {
#pragma HLS UNROLL
                        int gi = ii + i;
                        int gj = jj + j;
                        tile_tmp[i][j] = (gi < NI && gj < NJ) ? tmp[gi][gj] : 0.0;
                    }
                }

                // Load tile of C[jj:jj+TJ][ll:ll+TL]
                load_C:
                for (int j = 0; j < TJ; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=TJ max=TJ
                    for (int l = 0; l < TL; l++) {
#pragma HLS UNROLL
                        int gj = jj + j;
                        int gl = ll + l;
                        tile_C[j][l] = (gj < NJ && gl < NL) ? C[gj][gl] : 0.0;
                    }
                }

                // Compute tile contribution
                // Pipeline the i-loop; unroll l and j to enable full parallelism
                compute2:
                for (int i = 0; i < TI; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=TI max=TI
#pragma HLS DEPENDENCE variable=acc_D inter false
                    for (int l = 0; l < TL; l++) {
#pragma HLS UNROLL
                        double sum = 0.0;
                        for (int j = 0; j < TJ; j++) {
#pragma HLS UNROLL
                            sum += tile_tmp[i][j] * tile_C[j][l];
                        }
                        acc_D[i][l] += sum;
                    }
                }
            } // jj

            // Store D tile back to global memory
            store_D:
            for (int i = 0; i < TI; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=TI max=TI
                for (int l = 0; l < TL; l++) {
#pragma HLS UNROLL
                    int gi = ii + i;
                    int gl = ll + l;
                    if (gi < NI && gl < NL)
                        D[gi][gl] = acc_D[i][l];
                }
            }

        } // ll
    } // ii
}

} // extern "C"
```

Looking at the current code, I can see that the inner loops within the pipelined loops are already fully unrolled (`#pragma HLS UNROLL` without factor). The key opportunity for unroll optimization is to **increase the tile sizes** and apply **partial unroll factors** to the outer tiled loops to expose more parallelism.

However, the instruction says to add `#pragma HLS UNROLL factor=N` to inner loops and adjust partitioning - the current code already has complete unroll on the innermost loops. The next step is to apply unroll to the **intermediate loops** (the `i` loop in compute sections) with a factor, and increase tile sizes to get more parallelism.

Let me increase tile sizes to 16 for I and L dimensions (which have trip counts that benefit), and apply unroll factor=2 to the outer pipelined loops while adjusting partitioning accordingly:

```cpp
#include "2mm.h"

// Tile sizes increased to improve parallelism with unrolling
#define TI 8
#define TJ 8
#define TK 8
#define TL 8

// Unroll factors for the pipelined i-loop
#define UI 2

extern "C" {

void kernel_2mm(   
		double alpha,
		double beta,
		double tmp[ NI + 0][NJ + 0],
		double A[ NI + 0][NK + 0],
		double B[ NK + 0][NJ + 0],
		double C[ NJ + 0][NL + 0],
		double D[ NI + 0][NL + 0])
{
#pragma HLS INTERFACE s_axilite port=alpha    bundle=control
#pragma HLS INTERFACE s_axilite port=beta     bundle=control
#pragma HLS INTERFACE m_axi     port=tmp      offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=tmp      bundle=control
#pragma HLS INTERFACE m_axi     port=A        offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=A        bundle=control
#pragma HLS INTERFACE m_axi     port=B        offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=B        bundle=control
#pragma HLS INTERFACE m_axi     port=C        offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=C        bundle=control
#pragma HLS INTERFACE m_axi     port=D        offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=D        bundle=control
#pragma HLS INTERFACE s_axilite port=return   bundle=control

    // -------------------------------------------------------
    // Phase 1: tmp[i][j] = alpha * sum_k( A[i][k] * B[k][j] )
    // Tile over i, j, k dimensions
    // -------------------------------------------------------

    double acc_tmp[TI][TJ];
