#include "2mm.h"
#include "../../../common/mc.h"

// Tile sizes increased to improve parallelism with unrolling
#define TI 8
#define TJ 8
#define TK 8
#define TL 8

// Unroll factors for the pipelined i-loop
#define UI 2

// Wide bus is 512 bits; double is 64 bits => 8 doubles per bus word
#define DOUBLES_PER_BUS (LARGE_BUS / 64)

extern "C" {

void kernel_2mm(   
		double alpha,
		double beta,
		MARS_WIDE_BUS_TYPE* tmp,
		MARS_WIDE_BUS_TYPE* A,
		MARS_WIDE_BUS_TYPE* B,
		MARS_WIDE_BUS_TYPE* C,
		MARS_WIDE_BUS_TYPE* D)
{
#pragma HLS INTERFACE s_axilite port=alpha    bundle=control
#pragma HLS INTERFACE s_axilite port=beta     bundle=control
#pragma HLS INTERFACE m_axi     port=tmp      offset=slave bundle=gmem0 max_read_burst_length=256 max_write_burst_length=256
#pragma HLS INTERFACE s_axilite port=tmp      bundle=control
#pragma HLS INTERFACE m_axi     port=A        offset=slave bundle=gmem1 max_read_burst_length=256 max_write_burst_length=256
#pragma HLS INTERFACE s_axilite port=A        bundle=control
#pragma HLS INTERFACE m_axi     port=B        offset=slave bundle=gmem2 max_read_burst_length=256 max_write_burst_length=256
#pragma HLS INTERFACE s_axilite port=B        bundle=control
#pragma HLS INTERFACE m_axi     port=C        offset=slave bundle=gmem3 max_read_burst_length=256 max_write_burst_length=256
#pragma HLS INTERFACE s_axilite port=C        bundle=control
#pragma HLS INTERFACE m_axi     port=D        offset=slave bundle=gmem4 max_read_burst_length=256 max_write_burst_length=256
#pragma HLS INTERFACE s_axilite port=D        bundle=control
#pragma HLS INTERFACE s_axilite port=return   bundle=control

    // -------------------------------------------------------
    // Phase 1: tmp[i][j] = alpha * sum_k( A[i][k] * B[k][j] )
    // Tile over i, j, k dimensions with double buffering on k tiles
    // -------------------------------------------------------

    double acc_tmp[TI][TJ];

    // Double-buffered tile arrays for A and B
    double tile_A_0[TI][TK];
    double tile_A_1[TI][TK];
    double tile_B_0[TK][TJ];
    double tile_B_1[TK][TJ];

    // Flat staging buffers for wide bus reads
    double flat_A[TI * TK];
    double flat_B[TK * TJ];
    double flat_tmp[TI * TJ];
    double flat_tmp_C[TI * TJ]; // for phase 2 tmp reads
    double flat_C[TJ * TL];
    double flat_D_r[TI * TL];   // for phase 2 D reads
    double flat_D_w[TI * TL];   // for phase 2 D writes

#pragma HLS ARRAY_PARTITION variable=acc_tmp  cyclic factor=UI dim=1
#pragma HLS ARRAY_PARTITION variable=acc_tmp  complete dim=2
#pragma HLS ARRAY_PARTITION variable=tile_A_0 cyclic factor=UI dim=1
#pragma HLS ARRAY_PARTITION variable=tile_A_0 complete dim=2
#pragma HLS ARRAY_PARTITION variable=tile_A_1 cyclic factor=UI dim=1
#pragma HLS ARRAY_PARTITION variable=tile_A_1 complete dim=2
#pragma HLS ARRAY_PARTITION variable=tile_B_0 complete dim=1
#pragma HLS ARRAY_PARTITION variable=tile_B_0 complete dim=2
#pragma HLS ARRAY_PARTITION variable=tile_B_1 complete dim=1
#pragma HLS ARRAY_PARTITION variable=tile_B_1 complete dim=2
#pragma HLS ARRAY_PARTITION variable=flat_A   cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=flat_B   cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=flat_tmp cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=flat_tmp_C cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=flat_C   cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=flat_D_r cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=flat_D_w cyclic factor=8 dim=1

    phase1_i:
    for (int ii = 0; ii < NI; ii += TI) {
#pragma HLS LOOP_TRIPCOUNT min=5 max=5
        phase1_j:
        for (int jj = 0; jj < NJ; jj += TJ) {
#pragma HLS LOOP_TRIPCOUNT min=7 max=7

            // Initialize accumulator tile
            init_acc:
            for (int i = 0; i < TI; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=UI
#pragma HLS LOOP_TRIPCOUNT min=TI max=TI
                for (int j = 0; j < TJ; j++) {
#pragma HLS UNROLL
                    acc_tmp[i][j] = 0.0;
                }
            }

            // Preload first k tile into buffer 0 using wide bus
            {
                int kk = 0;
                // Load A tile rows one at a time using wide bus
                load_A_pre_rows:
                for (int i = 0; i < TI; i++) {
#pragma HLS LOOP_TRIPCOUNT min=TI max=TI
                    int gi = ii + i;
                    int gk = kk;
                    if (gi < NI && gk < NK) {
                        memcpy_wide_bus_read_double(flat_A + i*TK, A,
                            (gi * NK + gk) * sizeof(double),
                            sizeof(double) * TK);
                    } else {
                        for (int k = 0; k < TK; k++) {
#pragma HLS UNROLL
                            flat_A[i*TK + k] = 0.0;
                        }
                    }
                }
                // Scatter flat_A into tile_A_0
                scatter_A_pre:
                for (int i = 0; i < TI; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=UI
                    for (int k = 0; k < TK; k++) {
#pragma HLS UNROLL
                        tile_A_0[i][k] = flat_A[i*TK + k];
                    }
                }

                // Load B tile rows using wide bus
                load_B_pre_rows:
                for (int k = 0; k < TK; k++) {
#pragma HLS LOOP_TRIPCOUNT min=TK max=TK
                    int gk = kk + k;
                    int gj = jj;
                    if (gk < NK && gj < NJ) {
                        memcpy_wide_bus_read_double(flat_B + k*TJ, B,
                            (gk * NJ + gj) * sizeof(double),
                            sizeof(double) * TJ);
                    } else {
                        for (int j = 0; j < TJ; j++) {
#pragma HLS UNROLL
                            flat_B[k*TJ + j] = 0.0;
                        }
                    }
                }
                // Scatter flat_B into tile_B_0
                scatter_B_pre:
                for (int k = 0; k < TK; k++) {
#pragma HLS PIPELINE II=1
                    for (int j = 0; j < TJ; j++) {
#pragma HLS UNROLL
                        tile_B_0[k][j] = flat_B[k*TJ + j];
                    }
                }
            }

            // Accumulate over k tiles with double buffering
            phase1_k:
            for (int kk = 0; kk < NK; kk += TK) {
#pragma HLS LOOP_TRIPCOUNT min=9 max=9

                int buf_sel = (kk / TK) % 2; // which buffer holds current tile
                int next_kk = kk + TK;

                // Load next tile into the other buffer (if not last)
                if (next_kk < NK) {
                    if (buf_sel == 0) {
                        // Load next into buffer 1 using wide bus
                        load_A_next_0_rows:
                        for (int i = 0; i < TI; i++) {
#pragma HLS LOOP_TRIPCOUNT min=TI max=TI
                            int gi = ii + i;
                            int gk = next_kk;
                            if (gi < NI && gk < NK) {
                                memcpy_wide_bus_read_double(flat_A + i*TK, A,
                                    (gi * NK + gk) * sizeof(double),
                                    sizeof(double) * TK);
                            } else {
                                for (int k = 0; k < TK; k++) {
#pragma HLS UNROLL
                                    flat_A[i*TK + k] = 0.0;
                                }
                            }
                        }
                        scatter_A_next_0:
                        for (int i = 0; i < TI; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=UI
                            for (int k = 0; k < TK; k++) {
#pragma HLS UNROLL
                                tile_A_1[i][k] = flat_A[i*TK + k];
                            }
                        }
                        load_B_next_0_rows:
                        for (int k = 0; k < TK; k++) {
#pragma HLS LOOP_TRIPCOUNT min=TK max=TK
                            int gk = next_kk + k;
                            int gj = jj;
                            if (gk < NK && gj < NJ) {
                                memcpy_wide_bus_read_double(flat_B + k*TJ, B,
                                    (gk * NJ + gj) * sizeof(double),
                                    sizeof(double) * TJ);
                            } else {
                                for (int j = 0; j < TJ; j++) {
#pragma HLS UNROLL
                                    flat_B[k*TJ + j] = 0.0;
                                }
                            }
                        }
                        scatter_B_next_0:
                        for (int k = 0; k < TK; k++) {
#pragma HLS PIPELINE II=1
                            for (int j = 0; j < TJ; j++) {
#pragma HLS UNROLL
                                tile_B_1[k][j] = flat_B[k*TJ + j];
                            }
                        }
                    } else {
                        // Load next into buffer 0 using wide bus
                        load_A_next_1_rows:
                        for (int i = 0; i < TI; i++) {
#pragma HLS LOOP_TRIPCOUNT min=TI max=TI
                            int gi = ii + i;
                            int gk = next_kk;
                            if (gi < NI && gk < NK) {
                                memcpy_wide_bus_read_double(flat_A + i*TK, A,
                                    (gi * NK + gk) * sizeof(double),
                                    sizeof(double) * TK);
                            } else {
                                for (int k = 0; k < TK; k++) {
#pragma HLS UNROLL
                                    flat_A[i*TK + k] = 0.0;
                                }
                            }
                        }
                        scatter_A_next_1:
                        for (int i = 0; i < TI; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=UI
                            for (int k = 0; k < TK; k++) {
#pragma HLS UNROLL
                                tile_A_0[i][k] = flat_A[i*TK + k];
                            }
                        }
                        load_B_next_1_rows:
                        for (int k = 0; k < TK; k++) {
#pragma HLS LOOP_TRIPCOUNT min=TK max=TK
                            int gk = next_kk + k;
                            int gj = jj;
                            if (gk < NK && gj < NJ) {
                                memcpy_wide_bus_read_double(flat_B + k*TJ, B,
                                    (gk * NJ + gj) * sizeof(double),
                                    sizeof(double) * TJ);
                            } else {
                                for (int j = 0; j < TJ; j++) {
#pragma HLS UNROLL
                                    flat_B[k*TJ + j] = 0.0;
                                }
                            }
                        }
                        scatter_B_next_1:
                        for (int k = 0; k < TK; k++) {
#pragma HLS PIPELINE II=1
                            for (int j = 0; j < TJ; j++) {
#pragma HLS UNROLL
                                tile_B_0[k][j] = flat_B[k*TJ + j];
                            }
                        }
                    }
                }

                // Compute from current buffer
                if (buf_sel == 0) {
                    compute1_0:
                    for (int i = 0; i < TI; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=UI
#pragma HLS LOOP_TRIPCOUNT min=TI max=TI
#pragma HLS DEPENDENCE variable=acc_tmp inter false
                        for (int j = 0; j < TJ; j++) {
#pragma HLS UNROLL
                            double sum = 0.0;
                            for (int k = 0; k < TK; k++) {
#pragma HLS UNROLL
                                sum += alpha * tile_A_0[i][k] * tile_B_0[k][j];
                            }
                            acc_tmp[i][j] += sum;
                        }
                    }
                } else {
                    compute1_1:
                    for (int i = 0; i < TI; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=UI
#pragma HLS LOOP_TRIPCOUNT min=TI max=TI
#pragma HLS DEPENDENCE variable=acc_tmp inter false
                        for (int j = 0; j < TJ; j++) {
#pragma HLS UNROLL
                            double sum = 0.0;
                            for (int k = 0; k < TK; k++) {
#pragma HLS UNROLL
                                sum += alpha * tile_A_1[i][k] * tile_B_1[k][j];
                            }
                            acc_tmp[i][j] += sum;
                        }
                    }
                }

            } // kk

            // Gather acc_tmp into flat buffer, then store via wide bus
            gather_tmp:
            for (int i = 0; i < TI; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=UI
                for (int j = 0; j < TJ; j++) {
#pragma HLS UNROLL
                    flat_tmp[i*TJ + j] = acc_tmp[i][j];
                }
            }
            // Store accumulated tmp tile to global memory via wide bus
            store_tmp_rows:
            for (int i = 0; i < TI; i++) {
#pragma HLS LOOP_TRIPCOUNT min=TI max=TI
                int gi = ii + i;
                int gj = jj;
                if (gi < NI && gj < NJ) {
                    int count = (jj + TJ <= NJ) ? TJ : (NJ - jj);
                    memcpy_wide_bus_write_double(tmp,
                        flat_tmp + i*TJ,
                        (gi * NJ + gj) * sizeof(double),
                        sizeof(double) * count);
                }
            }

        } // jj
    } // ii

    // -------------------------------------------------------
    // Phase 2: D[i][l] = beta * D[i][l] + sum_k( tmp[i][k] * C[k][l] )
    // Tile over i, l, j dimensions with double buffering on j tiles
    // -------------------------------------------------------

    double acc_D[TI][TL];

    // Double-buffered tile arrays for tmp and C
    double tile_tmp_0[TI][TJ];
    double tile_tmp_1[TI][TJ];
    double tile_C_0[TJ][TL];
    double tile_C_1[TJ][TL];

#pragma HLS ARRAY_PARTITION variable=acc_D     cyclic factor=UI dim=1
#pragma HLS ARRAY_PARTITION variable=acc_D     complete dim=2
#pragma HLS ARRAY_PARTITION variable=tile_tmp_0 cyclic factor=UI dim=1
#pragma HLS ARRAY_PARTITION variable=tile_tmp_0 complete dim=2
#pragma HLS ARRAY_PARTITION variable=tile_tmp_1 cyclic factor=UI dim=1
#pragma HLS ARRAY_PARTITION variable=tile_tmp_1 complete dim=2
#pragma HLS ARRAY_PARTITION variable=tile_C_0  complete dim=1
#pragma HLS ARRAY_PARTITION variable=tile_C_0  complete dim=2
#pragma HLS ARRAY_PARTITION variable=tile_C_1  complete dim=1
#pragma HLS ARRAY_PARTITION variable=tile_C_1  complete dim=2

    phase2_i:
    for (int ii = 0; ii < NI; ii += TI) {
#pragma HLS LOOP_TRIPCOUNT min=5 max=5
        phase2_l:
        for (int ll = 0; ll < NL; ll += TL) {
#pragma HLS LOOP_TRIPCOUNT min=10 max=10

            // Load and initialize accumulator: acc_D = beta * D[ii:ii+TI][ll:ll+TL]
            // Use wide bus to load D tile
            load_D_rows:
            for (int i = 0; i < TI; i++) {
#pragma HLS LOOP_TRIPCOUNT min=TI max=TI
                int gi = ii + i;
                int gl = ll;
                if (gi < NI && gl < NL) {
                    int count = (ll + TL <= NL) ? TL : (NL - ll);
                    memcpy_wide_bus_read_double(flat_D_r + i*TL, D,
                        (gi * NL + gl) * sizeof(double),
                        sizeof(double) * count);
                } else {
                    for (int l = 0; l < TL; l++) {
#pragma HLS UNROLL
                        flat_D_r[i*TL + l] = 0.0;
                    }
                }
            }
            init_D:
            for (int i = 0; i < TI; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=UI
#pragma HLS LOOP_TRIPCOUNT min=TI max=TI
                for (int l = 0; l < TL; l++) {
#pragma HLS UNROLL
                    int gi = ii + i;
                    int gl = ll + l;
                    acc_D[i][l] = (gi < NI && gl < NL) ? beta * flat_D_r[i*TL + l] : 0.0;
                }
            }

            // Preload first j tile into buffer 0 using wide bus
            {
                int jj = 0;
                load_tmp_pre_rows:
                for (int i = 0; i < TI; i++) {
#pragma HLS LOOP_TRIPCOUNT min=TI max=TI
                    int gi = ii + i;
                    int gj = jj;
                    if (gi < NI && gj < NJ) {
                        memcpy_wide_bus_read_double(flat_tmp_C + i*TJ, tmp,
                            (gi * NJ + gj) * sizeof(double),
                            sizeof(double) * TJ);
                    } else {
                        for (int j = 0; j < TJ; j++) {
#pragma HLS UNROLL
                            flat_tmp_C[i*TJ + j] = 0.0;
                        }
                    }
                }
                scatter_tmp_pre:
                for (int i = 0; i < TI; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=UI
                    for (int j = 0; j < TJ; j++) {
#pragma HLS UNROLL
                        tile_tmp_0[i][j] = flat_tmp_C[i*TJ + j];
                    }
                }
                load_C_pre_rows:
                for (int j = 0; j < TJ; j++) {
#pragma HLS LOOP_TRIPCOUNT min=TJ max=TJ
                    int gj = jj + j;
                    int gl = ll;
                    if (gj < NJ && gl < NL) {
                        memcpy_wide_bus_read_double(flat_C + j*TL, C,
                            (gj * NL + gl) * sizeof(double),
                            sizeof(double) * TL);
                    } else {
                        for (int l = 0; l < TL; l++) {
#pragma HLS UNROLL
                            flat_C[j*TL + l] = 0.0;
                        }
                    }
                }
                scatter_C_pre:
                for (int j = 0; j < TJ; j++) {
#pragma HLS PIPELINE II=1
                    for (int l = 0; l < TL; l++) {
#pragma HLS UNROLL
                        tile_C_0[j][l] = flat_C[j*TL + l];
                    }
                }
            }

            // Accumulate over j tiles with double buffering
            phase2_k:
            for (int jj = 0; jj < NJ; jj += TJ) {
#pragma HLS LOOP_TRIPCOUNT min=7 max=7

                int buf_sel = (jj / TJ) % 2;
                int next_jj = jj + TJ;

                // Load next tile into the other buffer (if not last)
                if (next_jj < NJ) {
                    if (buf_sel == 0) {
                        // Load next into buffer 1 using wide bus
                        load_tmp_next_0_rows:
                        for (int i = 0; i < TI; i++) {
#pragma HLS LOOP_TRIPCOUNT min=TI max=TI
                            int gi = ii + i;
                            int gj = next_jj;
                            if (gi < NI && gj < NJ) {
                                memcpy_wide_bus_read_double(flat_tmp_C + i*TJ, tmp,
                                    (gi * NJ + gj) * sizeof(double),
                                    sizeof(double) * TJ);
                            } else {
                                for (int j = 0; j < TJ; j++) {
#pragma HLS UNROLL
                                    flat_tmp_C[i*TJ + j] = 0.0;
                                }
                            }
                        }
                        scatter_tmp_next_0:
                        for (int i = 0; i < TI; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=UI
                            for (int j = 0; j < TJ; j++) {
#pragma HLS UNROLL
                                tile_tmp_1[i][j] = flat_tmp_C[i*TJ + j];
                            }
                        }
                        load_C_next_0_rows:
                        for (int j = 0; j < TJ; j++) {
#pragma HLS LOOP_TRIPCOUNT min=TJ max=TJ
                            int gj = next_jj + j;
                            int gl = ll;
                            if (gj < NJ && gl < NL) {
                                memcpy_wide_bus_read_double(flat_C + j*TL, C,
                                    (gj * NL + gl) * sizeof(double),
                                    sizeof(double) * TL);
                            } else {
                                for (int l = 0; l < TL; l++) {
#pragma HLS UNROLL
                                    flat_C[j*TL + l] = 0.0;
                                }
                            }
                        }
                        scatter_C_next_0:
                        for (int j = 0; j < TJ; j++) {
#pragma HLS PIPELINE II=1
                            for (int l = 0; l < TL; l++) {
#pragma HLS UNROLL
                                tile_C_1[j][l] = flat_C[j*TL + l];
                            }
                        }
                    } else {
                        // Load next into buffer 0 using wide bus
                        load_tmp_next_1_rows:
                        for (int i = 0; i < TI; i++) {
#pragma HLS LOOP_TRIPCOUNT min=TI max=TI
                            int gi = ii + i;
                            int gj = next_jj;
                            if (gi < NI && gj < NJ) {
                                memcpy_wide_bus_read_double(flat_tmp_C + i*TJ, tmp,
                                    (gi * NJ + gj) * sizeof(double),
                                    sizeof(double) * TJ);
                            } else {
                                for (int j = 0; j < TJ; j++) {
#pragma HLS UNROLL
                                    flat_tmp_C[i*TJ + j] = 0.0;
                                }
                            }
                        }
                        scatter_tmp_next_1:
                        for (int i = 0; i < TI; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=UI
                            for (int j = 0; j < TJ; j++) {
#pragma HLS UNROLL
                                tile_tmp_0[i][j] = flat_tmp_C[i*TJ + j];
                            }
                        }
                        load_C_next_1_rows:
                        for (int j = 0; j < TJ; j++) {
#pragma HLS LOOP_TRIPCOUNT min=TJ max=TJ
                            int gj = next_jj + j;
                            int gl = ll;
                            if (gj < NJ && gl < NL) {
                                memcpy_wide_bus_read_double(flat_C + j*TL, C,
                                    (gj * NL + gl) * sizeof(double),
                                    sizeof(double) * TL);
                            } else {
                                for (int l = 0; l < TL; l++) {
#pragma HLS UNROLL
                                    flat_C[j*TL + l] = 0.0;
                                }
                            }
                        }
                        scatter_C_next_1:
                        for (int j = 0; j < TJ; j++) {
#pragma HLS PIPELINE II=1
                            for (int l = 0; l < TL; l++) {
#pragma HLS UNROLL
                                tile_C_0[j][l] = flat_C[j*TL + l];
                            }
                        }
                    }
                }

                // Compute from current buffer
                if (buf_sel == 0) {
                    compute2_0:
                    for (int i = 0; i < TI; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=UI
#pragma HLS LOOP_TRIPCOUNT min=TI max=TI
#pragma HLS DEPENDENCE variable=acc_D inter false
                        for (int l = 0; l < TL; l++) {
#pragma HLS UNROLL
                            double sum = 0.0;
                            for (int j = 0; j < TJ; j++) {
#pragma HLS UNROLL
                                sum += tile_tmp_0[i][j] * tile_C_0[j][l];
                            }
                            acc_D[i][l] += sum;
                        }
                    }
                } else {
                    compute2_1:
                    for (int i = 0; i < TI; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=UI
#pragma HLS LOOP_TRIPCOUNT min=TI max=TI
#pragma HLS DEPENDENCE variable=acc_D inter false
                        for (int l = 0; l < TL; l++) {
#pragma HLS UNROLL
                            double sum = 0.0;
                            for (int j = 0; j < TJ; j++) {
#pragma HLS UNROLL
                                sum += tile_tmp_1[i][j] * tile_C_1[j][l];
                            }
                            acc_D[i][l] += sum;
                        }
                    }
                }

            } // jj

            // Gather acc_D into flat buffer, then store via wide bus
            gather_D:
            for (int i = 0; i < TI; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=UI
                for (int l = 0; l < TL; l++) {
#pragma HLS UNROLL
                    flat_D_w[i*TL + l] = acc_D[i][l];
                }
            }
            // Store D tile back to global memory via wide bus
            store_D_rows:
            for (int i = 0; i < TI; i++) {
#pragma HLS LOOP_TRIPCOUNT min=TI max=TI
                int gi = ii + i;
                int gl = ll;
                if (gi < NI &&
